package com.midtermwork;
import org.junit.Test;
import static org.junit.Assert.*;
public class LearningChecks {
 private GameWorld quiet(){GameWorld w=new GameWorld();w.enemies.clear();return w;}
 private void resolve(GameWorld w){while(w.choosingSkill())w.skipLearning();}
 private void level(GameWorld w,int n){while(w.level<n){w.addExperience(w.xpRequired()-w.xp);resolve(w);}}
 private void tick(GameWorld w,int frames){for(int n=0;n<frames;n++)w.step(1f/60,0,false,false);}
 @Test public void scarletVioletLevelScheduleAndInitialMoves(){GameWorld w=quiet();assertEquals(GameWorld.Skill.SCRATCH,w.skillAt(0));assertEquals(GameWorld.Skill.GROWL,w.skillAt(1));assertNull(w.skillAt(2));int[] expected={1,1,4,8,12,17,20,24,28,32,36,40};java.util.List<Integer> actual=new java.util.ArrayList<>();int tm=0;for(GameWorld.Skill skill:GameWorld.Skill.values()){if(skill.unlockLevel>0)actual.add(skill.unlockLevel);if(skill.tm)tm++;}java.util.Collections.sort(actual);assertEquals(expected.length,actual.size());for(int i=0;i<expected.length;i++)assertEquals(expected[i],actual.get(i).intValue());assertEquals(46,tm);}
 @Test public void levelFourOffersChoiceAndWorldFreezesUntilSelected(){GameWorld w=quiet();level(w,3);w.addExperience(w.xpRequired());assertEquals(GameWorld.Skill.EMBER,w.pendingSkill());float x=w.x,t=w.elapsed;tick(w,120);assertEquals(x,w.x,0);assertEquals(t,w.elapsed,0);assertFalse(w.trySkill(0));assertTrue(w.learnInto(2));assertEquals(GameWorld.Skill.EMBER,w.skillAt(2));assertFalse(w.choosingSkill());assertTrue(w.trySkill(2));tick(w,20);assertFalse(w.skillShots.isEmpty());assertEquals(GameWorld.Skill.EMBER,w.skillShots.get(0).move);}
 @Test public void everyCrossedLearningLevelQueuesOnceAndSkipLeavesSlotsAlone(){GameWorld w=quiet();while(w.level<40)w.addExperience(w.xpRequired()-w.xp);int previous=1,count=0;while(w.choosingSkill()){assertTrue(w.pendingSkill().unlockLevel>previous);previous=w.pendingSkill().unlockLevel;w.skipLearning();count++;}assertEquals(10,count);assertEquals(GameWorld.Skill.SCRATCH,w.skillAt(0));}
 @Test public void tmIsSpentOnlyAfterMoveAndSlotBothSelected(){GameWorld w=quiet();w.collectItem(GameWorld.Item.TM);assertTrue(w.tmSelecting);assertEquals(1,w.itemCount(GameWorld.Item.TM));assertTrue(w.chooseTm(GameWorld.Skill.FIRE_BLAST));assertEquals(1,w.itemCount(GameWorld.Item.TM));assertTrue(w.learnInto(3));assertEquals(GameWorld.Skill.FIRE_BLAST,w.skillAt(3));assertEquals(0,w.itemCount(GameWorld.Item.TM));assertFalse(w.choosingSkill());}
 @Test public void cancellingAtEitherTmStepPreservesChargesAndNoDuplicateMoves(){GameWorld w=quiet();w.collectItem(GameWorld.Item.TM);w.skipLearning();assertEquals(1,w.itemCount(GameWorld.Item.TM));assertTrue(w.openTm());assertTrue(w.chooseTm(GameWorld.Skill.PROTECT));w.skipLearning();assertEquals(1,w.itemCount(GameWorld.Item.TM));assertTrue(w.openTm());assertTrue(w.chooseTm(GameWorld.Skill.PROTECT));assertTrue(w.learnInto(2));w.collectItem(GameWorld.Item.TM);assertFalse(w.chooseTm(GameWorld.Skill.PROTECT));assertFalse(w.tmOptions().contains(GameWorld.Skill.PROTECT));w.skipLearning();assertEquals(1,w.itemCount(GameWorld.Item.TM));}
 @Test public void learningReplacementDoesNotMoveOtherSlots(){GameWorld w=quiet();level(w,3);w.addExperience(w.xpRequired());assertTrue(w.learnInto(1));assertEquals(GameWorld.Skill.EMBER,w.skillAt(1));assertEquals(GameWorld.Skill.SCRATCH,w.skillAt(0));assertNull(w.skillAt(2));}
 @Test public void retryRestoresEntryMovesAndTmCharges(){GameWorld w=quiet();w.collectItem(GameWorld.Item.TM);w.chooseTm(GameWorld.Skill.PROTECT);w.learnInto(2);w.stageComplete=true;assertTrue(w.advanceStage());w.collectItem(GameWorld.Item.TM);w.chooseTm(GameWorld.Skill.FIRE_BLAST);w.learnInto(2);assertEquals(GameWorld.Skill.FIRE_BLAST,w.skillAt(2));w.hp=0;assertTrue(w.retryStage());assertEquals(GameWorld.Skill.PROTECT,w.skillAt(2));assertEquals(0,w.itemCount(GameWorld.Item.TM));assertFalse(w.choosingSkill());}
 @Test public void candyDoesNotHealEvenWhenItEvolves(){GameWorld w=quiet();level(w,15);w.hp=1;w.collectItem(GameWorld.Item.CANDY);assertEquals(16,w.level);assertEquals(1,w.evolution);assertEquals(8,w.maxHp);assertEquals(1,w.hp);}
 @Test public void toolsMatchTypeAndCategoryAcrossNewMoves(){GameWorld w=quiet();int fire=w.skillDamage(GameWorld.Skill.FIRE_BLAST),rock=w.skillDamage(GameWorld.Skill.ROCK_SLIDE);w.collectItem(GameWorld.Item.CHARCOAL);assertEquals(Math.round(fire*1.2f),w.skillDamage(GameWorld.Skill.FIRE_BLAST));assertEquals(rock,w.skillDamage(GameWorld.Skill.ROCK_SLIDE));w.collectItem(GameWorld.Item.MUSCLE);assertTrue(w.skillDamage(GameWorld.Skill.ROCK_SLIDE)>rock);int special=w.skillDamage(GameWorld.Skill.SWIFT);w.collectItem(GameWorld.Item.GLASSES);assertTrue(w.skillDamage(GameWorld.Skill.SWIFT)>special);special=w.skillDamage(GameWorld.Skill.SWIFT);w.collectItem(GameWorld.Item.SCARF);assertTrue(w.skillDamage(GameWorld.Skill.SWIFT)>special);assertEquals(0,w.skillDamage(GameWorld.Skill.GROWL));}
 @Test public void everyCatalogMoveHasUsableCombatBehavior(){for(GameWorld.Skill move:GameWorld.Skill.values()){GameWorld w=quiet();w.level=20;w.invulnerable=0;TestWorlds.equip(w,move,GameWorld.Skill.SCRATCH);if(move==GameWorld.Skill.SLEEP_TALK)w.sleepTime=2;GameWorld.Enemy e=new GameWorld.Enemy(195,112,true);e.hp=e.maxHp=5000;e.timer=100;w.enemies.add(e);assertTrue(move.name,w.trySkill(0));tick(w,35);assertTrue(move.name,w.skillCooldowns[0]>0);if(move.category!=GameWorld.Category.STATUS||move==GameWorld.Skill.SLEEP_TALK)assertTrue(move.name,e.hp<5000);else if(move==GameWorld.Skill.SMOKE)assertFalse(w.smokeClouds.isEmpty());else if(move==GameWorld.Skill.GROWL)assertTrue(e.weakened>0);else if(move==GameWorld.Skill.SCARY_FACE)assertEquals(-2,e.speedStage);else if(move==GameWorld.Skill.ROAR)assertTrue(e.slowTime>0);else if(move==GameWorld.Skill.WILL_O_WISP)assertTrue(e.burnTime>0);else if(move==GameWorld.Skill.REST)assertTrue(w.sleepTime>0);}}
 @Test public void falseSwipeAndEchoNeverKill(){GameWorld w=quiet();TestWorlds.equip(w,GameWorld.Skill.FALSE_SWIPE);w.collectItem(GameWorld.Item.MULTI);GameWorld.Enemy e=new GameWorld.Enemy(195,112,true);e.hp=3;e.timer=100;w.enemies.add(e);w.trySkill(0);tick(w,50);assertEquals(1,e.hp);assertEquals(0,w.kills);}
 @Test public void protectAllowsMovementAndEndurePreservesHalfHeart(){GameWorld w=quiet();TestWorlds.equip(w,GameWorld.Skill.PROTECT);w.trySkill(0);tick(w,20);float x=w.x;w.step(1f/30,1,false,false);assertTrue(w.x>x);int hp=w.hp;w.damage(3,300);assertEquals(hp,w.hp);w.invulnerable=0;w.endureTime=4;w.damage(99,300);assertEquals(1,w.hp);}
 @Test public void deathClosesLearningAndRetryClearsPendingQueue(){GameWorld w=quiet();level(w,3);w.addExperience(w.xpRequired());assertTrue(w.choosingSkill());w.hp=0;assertFalse(w.choosingSkill());assertTrue(w.retryStage());assertFalse(w.choosingSkill());assertNull(w.pendingSkill());}
 @Test public void learningMenuBlocksDamageAndDropThrough(){GameWorld w=quiet();level(w,3);w.addExperience(w.xpRequired());w.invulnerable=0;int hp=w.hp;w.damage(3,300);assertEquals(hp,w.hp);assertFalse(w.dropThrough());}
}